package com.supersports.support;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;
final class SupportRules{private SupportRules(){}static String text(String value,int max){if(value==null||value.isBlank()||value.trim().length()>max)throw new IllegalArgumentException("Text is empty or exceeds its limit");return value.trim();}static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}static boolean transition(String from,String to){return switch(from){case "OPEN"->to.equals("IN_PROGRESS")||to.equals("RESOLVED");case "IN_PROGRESS"->to.equals("WAITING_FOR_CUSTOMER")||to.equals("RESOLVED");case "WAITING_FOR_CUSTOMER"->to.equals("IN_PROGRESS")||to.equals("RESOLVED");case "RESOLVED"->to.equals("OPEN");default->false;};}}
